using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("ISO country code, e.g. 'US'")] string? countryCode = null)
    {
        var query = countryCode is not null ? $"{city},{countryCode}" : city;
        var url = $"https://api.weatherapi.com/v1/current.json?key=demo&q={Uri.EscapeDataString(query)}";

        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(url);
        if (response is null)
            return "Unable to retrieve weather data.";

        return $"""
            Weather for {response.Location.Name}, {response.Location.Country}:
              Condition: {response.Current.Condition.Text}
              Temperature: {response.Current.TempC}°C / {response.Current.TempF}°F
              Humidity: {response.Current.Humidity}%
              Wind: {response.Current.WindKph} km/h
            """;
    }

    [McpServerTool, Description("Search for locations matching a query string.")]
    public async Task<string> SearchLocations(
        [Description("Search query (city name, zip, coordinates)")] string query)
    {
        var url = $"https://api.weatherapi.com/v1/search.json?key=demo&q={Uri.EscapeDataString(query)}";
        var results = await _httpClient.GetFromJsonAsync<LocationResult[]>(url);

        if (results is null || results.Length == 0)
            return "No locations found.";

        return string.Join("\n", results.Select(r => $"- {r.Name}, {r.Region}, {r.Country}"));
    }
}

// Response models
public record WeatherResponse(
    [property: JsonPropertyName("location")] LocationInfo Location,
    [property: JsonPropertyName("current")] CurrentWeather Current);

public record LocationInfo(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("country")] string Country);

public record CurrentWeather(
    [property: JsonPropertyName("temp_c")] double TempC,
    [property: JsonPropertyName("temp_f")] double TempF,
    [property: JsonPropertyName("humidity")] int Humidity,
    [property: JsonPropertyName("wind_kph")] double WindKph,
    [property: JsonPropertyName("condition")] WeatherCondition Condition);

public record WeatherCondition(
    [property: JsonPropertyName("text")] string Text);

public record LocationResult(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("region")] string Region,
    [property: JsonPropertyName("country")] string Country);

