using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "weather-mcp", Version = "1.0.0" };
    })
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

// Register a named HttpClient that the SDK injects into tool instances
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.Add("User-Agent", "McpWeatherServer/1.0");
    client.Timeout = TimeSpan.FromSeconds(30);
});

await builder.Build().RunAsync();

